/**
 * Value selection from a numeric range (`design/components/slider.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/slider.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/slider'

import {
  MEMBER_PROVIDERS,
  Ref,
  Spread,
  agentMember,
  derived,
  elementRef,
  mergeParts,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/controls/slider.module.css'

/** Value selection from a numeric range: the inputs it takes, by the React member's prop names. */
export interface SliderProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: number | [number, number]
  disabled?: boolean
  /**
   * Formats both the readout and `aria-valuetext`.
   */
  formatValue?: (value: number) => string
  invalid?: boolean
  max?: number
  min?: number
  /**
   * Two thumbs on one track. The pair is `[low, high]` and the thumbs cannot cross.
   */
  range?: boolean
  /**
   * Shows the current value at the row's end. Decorative, because the thumb announces it.
   */
  showValue?: boolean
  step?: number
  value?: number | [number, number]
}

/** Value selection from a numeric range. */
@Component({
  selector: 'pm-slider',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Spread],
  // prettier-ignore
  template: `<!-- root -->
<div
[attr.class]="e1()"
[attr.data-disabled]="e2()"
[attr.data-invalid]="e3()"
data-orientation="horizontal"
data-member="slider"
[pmRef]="root"
>@if (e4()) {<span
[attr.class]="e5()"
aria-hidden="true"
>{{ e6() }}</span>}
<!-- control -->
<div
[pmSpread]="e7()"
><!-- track -->
<div
[pmSpread]="e8()"
><!-- range -->
<div
[pmSpread]="e9()"
></div></div>
@for (_thumb of e10(); track e11($index); let index = $index) {<!-- thumb -->
<div
[pmSpread]="e12(index)"
></div>}</div></div>`,
})
export class Slider {
  static readonly controlKind = 'group'
  readonly ariaDescribedby = input<SliderProps['aria-describedby']>(undefined, {
    alias: 'aria-describedby',
  })
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  readonly ariaLabel = input<SliderProps['aria-label']>(undefined, { alias: 'aria-label' })
  readonly ariaLabelledby = input<SliderProps['aria-labelledby']>(undefined, {
    alias: 'aria-labelledby',
  })
  readonly ariaRequired = input<SliderProps['aria-required']>(undefined, { alias: 'aria-required' })
  readonly defaultValue = input<SliderProps['defaultValue']>(undefined)
  readonly disabled = input<Exclude<SliderProps['disabled'], undefined>, SliderProps['disabled']>(
    false,
    { transform: (value: SliderProps['disabled']) => (value === undefined ? false : value) },
  )
  /**
   * Formats both the readout and `aria-valuetext`.
   */
  readonly formatValue = input<
    Exclude<SliderProps['formatValue'], undefined>,
    SliderProps['formatValue']
  >(String, {
    transform: (value: SliderProps['formatValue']) => (value === undefined ? String : value),
  })
  readonly invalid = input<Exclude<SliderProps['invalid'], undefined>, SliderProps['invalid']>(
    false,
    { transform: (value: SliderProps['invalid']) => (value === undefined ? false : value) },
  )
  readonly max = input<Exclude<SliderProps['max'], undefined>, SliderProps['max']>(100, {
    transform: (value: SliderProps['max']) => (value === undefined ? 100 : value),
  })
  readonly min = input<Exclude<SliderProps['min'], undefined>, SliderProps['min']>(0, {
    transform: (value: SliderProps['min']) => (value === undefined ? 0 : value),
  })
  /**
   * Two thumbs on one track. The pair is `[low, high]` and the thumbs cannot cross.
   */
  readonly range = input<Exclude<SliderProps['range'], undefined>, SliderProps['range']>(false, {
    transform: (value: SliderProps['range']) => (value === undefined ? false : value),
  })
  /**
   * Shows the current value at the row's end. Decorative, because the thumb announces it.
   */
  readonly showValue = input<
    Exclude<SliderProps['showValue'], undefined>,
    SliderProps['showValue']
  >(false, {
    transform: (value: SliderProps['showValue']) => (value === undefined ? false : value),
  })
  readonly step = input<Exclude<SliderProps['step'], undefined>, SliderProps['step']>(1, {
    transform: (value: SliderProps['step']) => (value === undefined ? 1 : value),
  })
  readonly value = input<SliderProps['value']>(undefined)
  readonly onChange = output<number | [number, number]>({ alias: 'change' })
  /**
   * Fires on release. Use it for expensive side effects instead of debouncing `onChange`. Radix
   * commits on pointer release and on each keyboard step, so a blurred slider never holds an
   * uncommitted value.
   */
  readonly onCommit = output<number | [number, number]>({ alias: 'commit' })
  protected readonly $ = useMember({
    kind: Slider.controlKind,
    events: ['change', 'commit'],
    props: {
      'aria-describedby': () => this.ariaDescribedby(),
      'aria-label': () => this.ariaLabel(),
      'aria-labelledby': () => this.ariaLabelledby(),
      'aria-required': () => this.ariaRequired(),
      defaultValue: () => this.defaultValue(),
      disabled: () => this.disabled(),
      formatValue: () => this.formatValue(),
      invalid: () => this.invalid(),
      max: () => this.max(),
      min: () => this.min(),
      range: () => this.range(),
      showValue: () => this.showValue(),
      step: () => this.step(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly root = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          value:
            this.$p.value === undefined
              ? undefined
              : Array.isArray(this.$p.value)
                ? [...this.$p.value]
                : [this.$p.value],
          defaultValue:
            (this.$p.defaultValue === undefined
              ? undefined
              : Array.isArray(this.$p.defaultValue)
                ? [...this.$p.defaultValue]
                : [this.$p.defaultValue]) ??
            (this.$p.range ? [this.$p.min, this.$p.min] : [this.$p.min]),
          min: this.$p.min,
          max: this.$p.max,
          step: this.$p.step,
          disabled: this.$p.disabled,
          invalid: this.$p.invalid,
          getAriaValueText: (details) => this.$p.formatValue(details.value),
          onValueChange: (details) => {
            this.$.emit(
              this.onChange,
              'onChange',
              this.$p.range
                ? [details.value[0] ?? this.$p.min, details.value[1] ?? this.$p.min]
                : (details.value[0] ?? this.$p.min),
            )
          },
          onValueChangeEnd: (details) => {
            this.$.emit(
              this.onCommit,
              'onCommit',
              this.$p.range
                ? [details.value[0] ?? this.$p.min, details.value[1] ?? this.$p.min]
                : (details.value[0] ?? this.$p.min),
            )
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly spoken = derived(() =>
    this.api.value.value.map((value) => this.$p.formatValue(value)),
  )
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.disabled ? '' : undefined
  }

  protected e3() {
    return this.$p.invalid ? '' : undefined
  }

  protected e4() {
    return this.$p.showValue
  }

  protected e5() {
    if (!this.$p.showValue) return undefined as never
    return styles.readout
  }

  protected e6() {
    if (!this.$p.showValue) return undefined as never
    return this.spoken.value.join('–')
  }

  protected e7() {
    return mergeParts(this.api.value.getRootProps(), this.api.value.getControlProps(), {
      class: styles.control,
    })
  }

  protected e8() {
    return mergeParts(this.api.value.getTrackProps(), { class: styles.track })
  }

  protected e9() {
    return mergeParts(this.api.value.getRangeProps(), { class: styles.range })
  }

  e10() {
    return this.api.value.value
  }

  protected e11(index: number) {
    return index
  }

  protected e12(index: number) {
    return mergeParts(this.api.value.getThumbProps({ index }), {
      class: styles.thumb,
      'aria-label': this.$p['aria-label'],
      'aria-labelledby': this.$p['aria-labelledby'],
      'aria-describedby': this.$p['aria-describedby'],
      'aria-required': this.$p['aria-required'],
      'aria-invalid': this.$p.invalid ? true : undefined,
      'data-state':
        Object(this.api.value.getThumbProps({ index }))['data-dragging'] === ''
          ? 'dragging'
          : undefined,
    })
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'Slider',
      element: () => this.root.value?.querySelector('[role="slider"]'),
      state: () => ({
        value: this.api.value.value[0] ?? this.$p.min,
        high: this.$p.range ? (this.api.value.value[1] ?? this.$p.min) : null,
        disabled: this.$p.disabled,
        invalid: this.$p.invalid,
      }),
      actions: {
        set: { argument: 'number', run: (value) => this.api.value.setThumbValue(0, value) },
        'set-high': {
          argument: 'number',
          run: (value) =>
            (() => {
              if (!this.$p.range) throw new Error('A single slider has one value, which set moves.')
              this.api.value.setThumbValue(1, value)
            })(),
        },
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
